// Embeds the application icon and a VERSIONINFO block into NuPhyLab.exe. The
// icon is generated by scripts/build-icon-win.mjs before cargo runs in the
// package chain; a missing icon must not break a plain dev rebuild.
use std::path::Path;

fn version_from_package_json() -> Option<(String, u64)> {
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(manifest.join("../../package.json")).ok()?;
    let value: serde_json::Value = serde_json::from_str(&text).ok()?;
    let version = value.get("version")?.as_str()?.to_string();
    // Windows VERSIONINFO requires four numeric components; the packed u64 is
    // MAJOR << 48 | MINOR << 32 | PATCH << 16 | RELEASE.
    let numbers: Vec<u64> = version
        .split('.')
        .map(|part| part.parse::<u64>().ok())
        .collect::<Option<_>>()?;
    if numbers.len() != 3 {
        return None;
    }
    let packed = (numbers[0] << 48) | (numbers[1] << 32) | (numbers[2] << 16);
    Some((format!("{version}.0"), packed))
}

fn main() {
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut resource = winresource::WindowsResource::new();
    let icon = manifest.join("../../assets/AppIcon.ico");
    if icon.is_file() {
        resource.set_icon(icon.to_str().expect("icon path is utf-8"));
    } else {
        println!("cargo:warning=assets/AppIcon.ico not found; run `npm run build:icon:win` for the exe icon");
    }
    if let Some((version, packed)) = version_from_package_json() {
        resource.set("FileDescription", "NuPhyLab");
        resource.set("ProductName", "NuPhyLab");
        resource.set("OriginalFilename", "NuPhyLab.exe");
        resource.set("LegalCopyright", "MIT License");
        resource.set_version_info(winresource::VersionInfo::PRODUCTVERSION, packed);
        resource.set_version_info(winresource::VersionInfo::FILEVERSION, packed);
        resource.set("ProductVersion", &version);
        resource.set("FileVersion", &version);
    }
    if let Err(error) = resource.compile() {
        // A failed resource compile must fail the build so it is never missed;
        // only windres absence (toolchain setup) degrades to a warning.
        if error.to_string().contains("windres") {
            println!("cargo:warning=windres unavailable; building without embedded icon/version info");
        } else {
            panic!("resource compile failed: {error}");
        }
    }
}
